command:
$ErrorActionPreference = 'Stop'
$sha = 'fb5d638198d1f73ce2cae4ec28d27046583c5204'
$wt = Join-Path $env:RUNNER_TEMP 'issue485-pr486-budget-validation'
if (Test-Path -LiteralPath $wt) { Remove-Item -LiteralPath $wt -Recurse -Force }
& git fetch --no-tags --depth=1 origin $sha
if ($LASTEXITCODE -ne 0) { throw 'git fetch failed' }
& git worktree add --detach $wt $sha
if ($LASTEXITCODE -ne 0) { throw 'git worktree add failed' }
try {
  Set-Location $wt
  $actual = (& git rev-parse HEAD).Trim()
  if ($actual -ne $sha) { throw "Exact-head mismatch: $actual" }
  foreach ($name in @('OPENROUTER_API_KEY','OPENROUTER_MANAGEMENT_KEY','DCOIR_OPENAI_API_KEY','OPENAI_API_KEY','DCOIR_GEMINI_API')) { Remove-Item "Env:$name" -ErrorAction SilentlyContinue }
  & python3 -m py_compile .github/dcoir_review/scripts/dcoir_review_first_pass_candidate_eval.py .github/dcoir_review/scripts/dcoir_review_first_pass_candidate_eval_selftest.py .github/dcoir_review/scripts/dcoir_review_first_pass_budget_eval.py .github/dcoir_review/scripts/dcoir_review_first_pass_budget_eval_selftest.py
  if ($LASTEXITCODE -ne 0) { throw 'Python compile failed' }
  & python3 .github/dcoir_review/scripts/dcoir_review_first_pass_candidate_eval_selftest.py
  if ($LASTEXITCODE -ne 0) { throw 'Candidate harness selftest failed' }
  & python3 .github/dcoir_review/scripts/dcoir_review_first_pass_budget_eval_selftest.py
  if ($LASTEXITCODE -ne 0) { throw 'Budget harness selftest failed' }
  $planPath = Join-Path $env:DCOIR_DOWNLOADS_DIR 'issue485-pr486-budget-plan.json'
  & python3 .github/dcoir_review/scripts/dcoir_review_first_pass_budget_eval.py --candidate sonnet5-high --max-tokens 32768 --output $planPath
  if ($LASTEXITCODE -ne 0) { throw 'Budget plan failed' }
  $plan = Get-Content -LiteralPath $planPath -Raw -Encoding UTF8 | ConvertFrom-Json
  if ($plan.mode -ne 'plan-no-network' -or [int]$plan.network_calls -ne 0 -or $plan.no_publication -ne $true -or [int]$plan.max_tokens -ne 32768 -or [int]$plan.case_counts.total -ne 14) { throw 'Budget plan contract mismatch' }
  if ([string]$plan.fail_closed_contract.finish_reason_length -notmatch 'output-budget-exhausted') { throw 'Budget plan missing length fail-closed contract' }
  if ([string]$plan.fail_closed_contract.invalid_json_or_missing_findings -notmatch 'invalid-structured-output') { throw 'Budget plan missing structured-output fail-closed contract' }
  $configLines = Get-Content -LiteralPath '.github/dcoir_review/openrouter-pr-review-pareto.yml' -Encoding UTF8
  $commands = New-Object System.Collections.Generic.List[string]
  $inside = $false
  foreach ($line in $configLines) {
    if ($line -eq 'validation_commands:') { $inside = $true; continue }
    if (-not $inside) { continue }
    if ($line -match '^[^ #\t].*:$') { break }
    if ($line -match '^\s*-\s+(.+)$') { [void]$commands.Add($Matches[1]) }
  }
  if ($commands.Count -ne 44) { throw "Expected 44 governed commands, got $($commands.Count)" }
  $i = 0
  foreach ($cmd in $commands) {
    $i++
    Write-Host "[$i/$($commands.Count)] $cmd"
    & cmd.exe /d /s /c $cmd
    if ($LASTEXITCODE -ne 0) { throw "Governed command failed [$i]: $cmd" }
  }
  $receipt = [ordered]@{ schema='dcoir_issue485_budget_validation_v1'; result='pass'; pr=486; exact_head_sha=$sha; candidate='sonnet5-high'; max_tokens=32768; network_calls=0; no_publication=$true; budget_selftest='pass'; candidate_selftest='pass'; governed_commands_passed=$commands.Count; governed_commands_failed=0; inference_credentials_removed=$true }
  $receiptPath = Join-Path $env:DCOIR_DOWNLOADS_DIR 'issue485-pr486-budget-validation-receipt.json'
  ($receipt | ConvertTo-Json -Depth 6) | Out-File -LiteralPath $receiptPath -Encoding utf8
  Write-Host 'Issue #485 / PR #486 output-budget deterministic validation passed.'
} finally {
  Set-Location $env:DCOIR_REPO_ROOT
  & git worktree remove --force $wt 2>$null
  & git worktree prune 2>$null
}
